// Run against the built frontend with node --test tests/stream-startup.test.mjs.
import assert from "node:assert/strict"
import { registerHooks } from "node:module"
import test from "node:test"

globalThis.document = {
    createElement: () => ({ classList: { add() {} } }),
    getElementById: () => null,
}
globalThis.window = new EventTarget()
navigator.getGamepads = () => []
// config.js is normally generated by the web server on request.
registerHooks({
    resolve(specifier, context, nextResolve) {
        if (specifier === "./config.js" && context.parentURL?.includes("/dist/")) {
            return { url: "data:text/javascript,export default {}", shortCircuit: true }
        }
        return nextResolve(specifier, context)
    },
})

class Socket extends EventTarget {
    static OPEN = 1
    static CONNECTING = 0
    static CLOSED = 3
    static sockets = []
    readyState = Socket.CONNECTING
    sent = []

    constructor() {
        super()
        Socket.sockets.push(this)
    }
    open() {
        this.readyState = Socket.OPEN
        this.dispatchEvent(new Event("open"))
    }
    close() {
        this.readyState = 2
        queueMicrotask(() => {
            this.readyState = Socket.CLOSED
            this.dispatchEvent(new Event("close"))
        })
    }
    receive(message) {
        this.dispatchEvent(new MessageEvent("message", { data: JSON.stringify(message) }))
    }
    send(message) {
        this.sent.push(JSON.parse(message))
    }
}

globalThis.WebSocket = Socket
const { ConnectionController } = await import("../dist/desktop/connection.js")
const { DiagnosticsBus } = await import("../dist/desktop/diagnostics.js")
const { desktopStrings } = await import("../dist/desktop/strings.js")
const { StreamSupportedVideoCodecs } = await import("../dist/api_bindings.js")
const { Stream } = await import("../dist/stream/index.js")
const { defaultStreamInputConfig } = await import("../dist/stream/input.js")
const { WebRTCTransport } = await import("../dist/stream/transport/webrtc.js")

const tick = () => new Promise(resolve => setImmediate(resolve))
const rejectHostApp = socket => socket.receive({
    DebugLog: {
        message: "The host could not launch the selected app. Check it on the host, then reconnect.",
        ty: "fatalDescription",
        code: "hostAppLaunchRejected",
    },
})

function fixture(t, dataTransport = "auto") {
    Socket.sockets = []
    // These tests drive the actual Stream and controller with synthetic I/O.
    t.mock.timers.enable({ apis: ["setTimeout"] })
    window.setTimeout = setTimeout
    window.clearTimeout = clearTimeout
    t.mock.method(WebRTCTransport.prototype, "initPeer", () => {})
    const stream = new Stream(
        { host_url: "https://test.invalid" }, 1, 1,
        { ...defaultStreamInputConfig(), dataTransport, videoSize: "720p" },
        [1280, 720], { allow_transport_webrtc: true, allow_transport_websockets: true },
    )
    t.mock.method(stream, "setTransport", transport => { stream.transport = transport })
    t.mock.method(stream, "createPipelines", async () => ({ H264: true }))
    stream.videoRenderer = { setup: async () => {} }
    stream.audioPlayer = { setup: async () => {} }
    const diagnostics = new DiagnosticsBus()
    const controller = new ConnectionController({
        target: stream,
        probeAuth: async () => "ok",
        isOnline: () => true,
        isVisible: () => true,
        diagnostics,
    })
    stream.addInfoListener(event => {
        if (event.detail.type === "lifecycle") controller.onLifecycle(event.detail.lifecycle)
    })
    const socket = Socket.sockets[0]
    socket.open()
    return { stream, socket, controller, diagnostics }
}

async function start(socket) {
    socket.receive({ Setup: { ice_servers: [] } })
    await tick()
    assert.ok(socket.sent.some(message => message.StartStream))
}

function hostReady(socket) {
    socket.receive({ ConnectionComplete: {
        capabilities: { touch: false },
        format: StreamSupportedVideoCodecs.H264,
        width: 1280, height: 720, fps: 60,
        audio_sample_rate: 48000, audio_channel_count: 2,
        audio_streams: 1, audio_coupled_streams: 1, audio_samples_per_frame: 240,
        audio_mapping: [0, 1, 0, 0, 0, 0, 0, 0],
    } })
}

test("peer failure waits for the host outcome and a rejection requires a manual retry", async t => {
    const { stream, socket, controller, diagnostics } = fixture(t)
    await start(socket)
    stream.transport.onclose("failednoconnect")
    t.mock.timers.tick(16000)
    await tick()
    assert.equal(socket.readyState, Socket.OPEN)
    assert.equal(Socket.sockets.length, 1)

    // A queued automatic recovery must also be invalidated by the fatal reason.
    stream.scheduleControlReconnect()
    rejectHostApp(socket)
    socket.close()
    await tick()
    controller.onOffline()
    controller.onOnline()
    controller.onVisibilityChange(true)
    t.mock.timers.tick(60000)
    await tick()
    assert.equal(Socket.sockets.length, 1)
    assert.equal(stream.getTransportDiagnostics().webRtcFallbackCount, 0)
    assert.equal(controller.getView().reason, "hostAppLaunchRejected")
    assert.match(desktopStrings("ko-KR").connection.reasons.hostAppLaunchRejected, /호스트/)
    assert.match(desktopStrings("en").connection.reasons.hostAppLaunchRejected, /launch/)
    assert.equal(await stream.reconnect("quality"), false)
    const failure = diagnostics.events().find(event => event.detail.outcome === "hostAppLaunchRejected")
    assert.deepEqual(Object.keys(failure.detail).sort(), ["elapsedMs", "outcome", "stage", "transport"])

    const retry = controller.manualReconnect()
    await tick()
    t.mock.timers.tick(500)
    await retry
    assert.equal(Socket.sockets.length, 2)
})

test("a fatal startup notice invalidates transport fallback already waiting to run", async t => {
    const { stream, socket, controller } = fixture(t)
    // A local pipeline failure schedules fallback without sending StartStream.
    stream.createPipelines = async () => null
    socket.receive({ Setup: { ice_servers: [] } })
    await tick()
    rejectHostApp(socket)
    socket.close()
    t.mock.timers.tick(20000)
    await tick()
    assert.equal(Socket.sockets.length, 1)
    assert.equal(stream.getTransportDiagnostics().webRtcFallbackCount, 0)
    assert.equal(controller.getView().reason, "hostAppLaunchRejected")
})

test("a transient socket loss retries with delay, and a manual stop cancels future recovery", async t => {
    const { stream, socket, controller } = fixture(t)
    await start(socket)
    socket.receive({ DebugLog: { message: "A connection is already active", ty: null } })
    socket.close()
    await tick()
    assert.equal(controller.getView().state, "reconnecting")
    t.mock.timers.tick(749)
    assert.equal(Socket.sockets.length, 1)
    t.mock.timers.tick(1)
    await tick()
    assert.equal(Socket.sockets.length, 2)

    Socket.sockets[1].close()
    await tick()
    await stream.stop()
    controller.onOnline()
    t.mock.timers.tick(60000)
    await tick()
    assert.equal(Socket.sockets.length, 2)
    assert.equal(await stream.reconnect(), false)
    assert.equal(controller.getView().state, "stopped")
})

test("WebSocket media startup also reports a terminal rejection without retrying", async t => {
    const { socket, controller } = fixture(t, "websocket")
    await start(socket)
    rejectHostApp(socket)
    socket.close()
    await tick()
    t.mock.timers.tick(60000)
    assert.equal(Socket.sockets.length, 1)
    assert.equal(controller.getView().reason, "hostAppLaunchRejected")
})

test("negotiation failure after host startup still falls back to WebSocket", async t => {
    const { stream, socket } = fixture(t)
    await start(socket)
    hostReady(socket)
    stream.transport.onclose("failednoconnect")
    await tick()
    t.mock.timers.tick(500)
    await tick()
    assert.equal(Socket.sockets.length, 2)
    assert.equal(stream.getTransportDiagnostics().webRtcFallbackCount, 1)
    const fallback = Socket.sockets[1]
    fallback.open()
    await start(fallback)
    assert.ok(fallback.sent.some(message => message.SetTransport === "WebSocket"))
})

test("a host that never answers uses the existing bounded control retry budget", async t => {
    const { socket, controller } = fixture(t)
    const delays = [750, 1500, 3000, 5000, 5000]
    let current = socket
    for (const delay of delays) {
        await start(current)
        t.mock.timers.tick(45000)
        await tick()
        assert.equal(current.readyState, Socket.CLOSED)
        t.mock.timers.tick(delay)
        await tick()
        current = Socket.sockets.at(-1)
        current.open()
    }
    await start(current)
    t.mock.timers.tick(45000)
    await tick()
    assert.equal(controller.getView().reason, "exhausted")
    t.mock.timers.tick(60000)
    assert.equal(Socket.sockets.length, 6)
})

test("startup diagnostics distinguish peer connection from a first video track", async t => {
    const { stream, socket, controller, diagnostics } = fixture(t)
    await start(socket)
    hostReady(socket)
    stream.transport.onconnect()
    await tick()
    assert.equal(controller.getView().state, "connecting")
    stream.markVideoReady("firstVideoTrack")
    stream.markVideoReady("firstVideoTrack")
    assert.equal(controller.getView().state, "connected")
    const stages = diagnostics.events().filter(event => event.code === "connection.startupTiming")
    assert.deepEqual(stages.map(event => event.detail.stage), [
        "controlSocketOpen", "hostStreamReady", "webrtcPeerConnected", "firstVideoTrack", "finished",
    ])
    assert.equal(stages.at(-1).detail.outcome, "videoReady")
    assert.ok(stages.every(event => event.detail.elapsedMs >= 0))
})
